import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { sanitizeRuntimeSource } from './runtime-source-cleanup.mjs';

const rootDir = process.cwd();
const outputFile = join(rootDir, 'wip-runtime.bundle.js');

// Un seul bundle, dans un ordre déterministe. Le chargeur de données préparées
// doit être installé avant les patches qui capturent loadCSVData.
const runtimeFiles = [
  'perf-runtime/p2-prepared-data.js',
  'wip-performance-patch.js',
  'wip-followup-patch.js',
  'wip-release-refine-patch.js',
  'wip-marker-novelty-green-patch.js',
  'wip-feedback-patch.js',
  'wip-stability-repair-patch.js',
  'wip-route-ui-refine-patch.js',
  'wip-responsive-device-patch.js',
  'wip-map-terrain-search-patch.js',
  'wip-smart-route-sync-patch.js',
  'wip-route-sector-final-fix-patch.js',
  'wip-route-status-compact-patch.js',
  'wip-table-excel-filters-date-sort-patch.js',
  'wip-undercarriage-filter-patch.js',
  'wip-canton-adaptive-filter-patch.js',
  'wip-filter-placeholder-cleanup-patch.js',
  'wip-siret-dedupe-patch.js',
  'wip-undercarriage-detail-ui-patch.js',
  'wip-release-target-precision-patch.js',
  'wip-undercarriage-modal-clean-patch.js',
  'wip-undercarriage-model-rules-patch.js',
  'wip-undercarriage-smr-filter-patch.js',
  'wip-undercarriage-custom-select-patch.js',
  'wip-undercarriage-badge-restore-patch.js',
  'wip-undercarriage-native-visual-final-patch.js',
  'wip-table-excel-filter-precision-patch.js',
  'wip-final-regression-fixes-patch.js',
  'wip-safe-undercarriage-home-route-patch.js',
  'wip-ui-cleanup-terrain-speed-patch.js',
  'wip-city-filter-input-fix-patch.js',
  'wip-stack-guard-patch.js'
];

const banner = [
  '/*',
  ' * Generated by scripts/build-runtime-bundle.mjs.',
  ' * Edit the source modules, then run npm run bundle.',
  ' * Runtime order is intentional: do not inject additional startup patches from index.html.',
  ' */',
  ''
].join('\n');

const bundle = runtimeFiles.map(fileName => {
  const source = readFileSync(join(rootDir, fileName), 'utf8').trim();
  const cleaned = sanitizeRuntimeSource(fileName, source).trim();
  return `/* ${fileName} */\n${cleaned}\n;`;
}).join('\n\n');

writeFileSync(outputFile, `${banner}${bundle}\n`, 'utf8');
console.log(`Generated wip-runtime.bundle.js from ${runtimeFiles.length} files.`);
